SELECT jsonb_build_object('tables', COALESCE((SELECT jsonb_agg(jsonb_build_object('name', c.relname, 'rls', c.relrowsecurity) ORDER BY c.relname) FROM pg_catalog.pg_class AS c JOIN pg_catalog.pg_namespace AS n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p')), '[]'::jsonb), 'buckets', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', b.id, 'public', b.public) ORDER BY b.id) FROM storage.buckets AS b), '[]'::jsonb)) AS configuration_inventory;